def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0

    def count_set_bits(n):
        return n.bit_count()

    # Using the inclusion-exclusion principle to count set bits in the range
    def bit_sum(n):
        total = 0
        for i in range(64):
            x = 1 << i
            total += ((n // (x * 2 + 1)) * x + min(max(n % (x * 2 + 1) - x + 1, 0), x))
        return total

    return bit_sum(hi) - bit_sum(lo - 1)
```

