from typing import List

def weighted_harmonic_mean(vals: List[float], weights: List[float]) -> float:
    if not vals or len(vals) != len(weights) or sum(weights) == 0:
        return 0.0

    weighted_sum = sum(w / v for v, w in zip(vals, weights))
    total_weight = sum(weights)

    result = total_weight / weighted_sum
    return round(result, 3)
