def longest_bitonic_length(nums: list[int]) -> int:
    if not nums:
        return 0

    n = len(nums)
    increasing = [1] * n
    decreasing = [1] * n

    for i in range(1, n):
        if nums[i] > nums[i - 1]:
            increasing[i] = increasing[i - 1] + 1

    for i in range(n - 2, -1, -1):
        if nums[i] > nums[i + 1]:
            decreasing[i] = decreasing[i + 1] + 1

    max_length = 0
    for i in range(n):
        max_length = max(max_length, increasing[i] + decreasing[i] - 1)

    return max_length
