def longest_bitonic_length(nums: List[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0

    # Initialize two arrays to store the length of increasing and decreasing subsequences
    lis = [1] * n
    lds = [1] * n

    # Compute the length of increasing subsequence for each element
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Compute the length of decreasing subsequence for each element
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if nums[i] > nums[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # The length of the longest bitonic subsequence is the maximum value of lis[i] + lds[i] - 1
    max_length = 0
    for i in range(n):
        max_length = max(max_length, lis[i] + lds[i] - 1)

    return max_length
