def smallest_lcs(a: str, b: str) -> str:
    m, n = len(a), len(b)
    dp = [["" for _ in range(n + 1)] for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + a[i - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1], key=len)

    lcs = dp[m][n]
    candidates = [lcs]

    for i in range(m + 1):
        for j in range(n + 1):
            if dp[i][j] == lcs:
                candidate = ""
                x, y = i, j
                while x > 0 and y > 0:
                    if a[x - 1] == b[y - 1]:
                        candidate = a[x - 1] + candidate
                        x -= 1
                        y -= 1
                    elif len(dp[x - 1][y]) > len(dp[x][y - 1]):
                        x -= 1
                    else:
                        y -= 1
                candidates.append(candidate)

    return min(candidates)
