from typing import List, Tuple

def is_safe(board: List[List[bool]], row: int, col: int, n: int) -> bool:
    for i in range(col):
        if board[row][i]:
            return False

    for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
        if board[i][j]:
            return False

    for i, j in zip(range(row, n, 1), range(col, -1, -1)):
        if board[i][j]:
            return False

    return True

def solve_n_queens_util(board: List[List[bool]], col: int, n: int, blocked: set[Tuple[int, int]]) -> int:
    if col >= n:
        return 1

    count = 0
    for i in range(n):
        if (i, col) not in blocked and is_safe(board, i, col, n):
            board[i][col] = True
            count += solve_n_queens_util(board, col + 1, n, blocked)
            board[i][col] = False

    return count

def count_queens(n: int, blocked: List[Tuple[int, int]]) -> int:
    if n == 0:
        return 1

    board = [[False for _ in range(n)] for _ in range(n)]
    blocked_set = set(blocked)
    return solve_n_queens_util(board, 0, n, blocked_set)
