from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    queue = deque([(start, False, 0)])
    visited = set()

    while queue:
        (x, y), broke_wall, steps = queue.popleft()

        if (x, y, broke_wall) in visited:
            continue
        visited.add((x, y, broke_wall))

        if (x, y) == end:
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                if grid[nx][ny] == '.':
                    queue.append(((nx, ny), broke_wall, steps + 1))
                elif grid[nx][ny] == '#' and not broke_wall:
                    queue.append(((nx, ny), True, steps + 1))

    return -1
