import re

def identifier_to_snake(name: str) -> str:
    # Remove non-alphanumeric characters except underscores and hyphens
    cleaned_name = re.sub(r'[^a-zA-Z0-9_-]', '', name)

    # Split on underscores and hyphens
    parts = re.split(r'[_-]+', cleaned_name)

    # Process each part to separate words based on capitalization rules
    snake_parts = []
    for part in parts:
        if part:
            snake_parts.append(part[0].lower())
            for i in range(1, len(part)):
                if part[i].isupper() and part[i-1].islower():
                    snake_parts[-1] += '_' + part[i].lower()
                elif part[i].isdigit() and part[i-1].isalpha():
                    snake_parts[-1] += '_' + part[i]
                else:
                    snake_parts[-1] += part[i].lower()

    return '_'.join(snake_parts)
