import re

def identifier_to_snake(name: str) -> str:
    # Split by underscores and hyphens
    parts = re.split(r'[-_]', name)
    # Filter out empty parts
    parts = [part for part in parts if part]
    # Initialize the result list
    result = []
    for part in parts:
        # Split the part into words based on the rules
        words = []
        i = 0
        while i < len(part):
            if part[i].isalpha():
                j = i + 1
                while j < len(part) and part[j].isalpha() and part[j].islower():
                    j += 1
                words.append(part[i:j])
                i = j
            elif part[i].isdigit():
                j = i + 1
                while j < len(part) and part[j].isdigit():
                    j += 1
                words.append(part[i:j])
                i = j
            else:
                i += 1
        result.extend(words)
    # Join the words with underscores
    return '_'.join(result)

