import operator

def evaluate_expression(expression: str) -> float:
    ops = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
        '**': operator.pow
    }

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        values.append(ops[operator](left, right))

    def greater_precedence(op1, op2):
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '**': 3}
        return precedence[op1] > precedence[op2]

    if not expression:
        raise ValueError("Empty expression")

    tokens = []
    i = 0
    while i < len(expression):
        if expression[i].isspace():
            i += 1
            continue
        elif expression[i] == '(':
            tokens.append(expression[i])
        elif expression[i] == ')':
            while tokens[-1] != '(':
                apply_operator(tokens, values)
            tokens.pop()  # Remove '('
        elif expression[i] in ops:
            while (tokens and tokens[-1] in ops and
                   greater_precedence(tokens[-1], expression[i])):
                apply_operator(tokens, values)
            tokens.append(expression[i])
        else:
            j = i + 1
            while j < len(expression) and expression[j].isdigit():
                j += 1
            if '.' in expression[i:j]:
                values.append(float(expression[i:j]))
            else:
                values.append(int(expression[i:j]))
            i = j - 1
        i += 1

    while tokens:
        apply_operator(tokens, values)

    if len(values) != 1:
        raise ValueError("Invalid expression")

    return values[0]

