import re

def decode_runs(encoded: str) -> str:
    decoded = []
    tokens = encoded.split('\\')
    for token in tokens:
        if '~' in token:
            char, count = token.rsplit('~', 1)
            decoded.append(char * int(count))
        else:
            decoded.append(token)
    return ''.join(decoded)
