from typing import List

def subsets_with_sum(nums: List[int], k: int) -> List[List[int]]:
    def backtrack(start, path, target):
        if target == 0:
            result.add(tuple(sorted(path)))
            return
        for i in range(start, len(nums)):
            if nums[i] > target:
                break
            backtrack(i + 1, path + [nums[i]], target - nums[i])

    nums.sort()
    result = set()
    backtrack(0, [], k)
    return sorted(list(result))
