    if not grid or not grid[0]:
        return []

    rows, cols = len(grid), len(grid[0])
    result = [[0] * cols for _ in range(rows)]

    def pour(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return
        result[r][c] += 1

    while True:
        changed = False
        for r in range(rows):
