def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or any(c not in '0123456789abcdefghijklmnopqrstuvwxyz' for c in number):
        raise ValueError("Invalid input")

    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Base must be between 2 and 36")

    if number.startswith('-'):
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    decimal_number = 0
    power = 0
    for digit in reversed(number):
        if '0' <= digit <= '9':
            value = ord(digit) - ord('0')
        else:
            value = ord(digit.lower()) - ord('a') + 10

        if value >= from_base:
            raise ValueError("Invalid digit in number for given base")

        decimal_number += value * (from_base ** power)
        power += 1

    if decimal_number == 0:
        return '0'

    result = ''
    while decimal_number > 0:
        remainder = decimal_number % to_base
        if remainder < 10:
            result = chr(remainder + ord('0')) + result
        else:
            result = chr(remainder - 10 + ord('a')) + result
        decimal_number //= to_base

    return '-' + result if is_negative else result
