def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not (2 <= from_base <= 36 and 2 <= to_base <= 36):
        raise ValueError("Base must be between 2 and 36")

    if not number:
        raise ValueError("Number cannot be empty")

    if from_base == to_base:
        return number

    # Handle negative numbers
    negative = number.startswith('-')
    if negative:
        number = number[1:]

    # Convert from from_base to decimal
    try:
        decimal_number = int(number, from_base)
    except ValueError:
        raise ValueError("Invalid digit for base {}".format(from_base))

    # Convert from decimal to to_base
    if decimal_number == 0:
        return '0'

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    result = []
    while decimal_number > 0:
        result.append(digits[decimal_number % to_base])
        decimal_number //= to_base

    if negative:
        result.append('-')

    return ''.join(reversed(result))
