def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or any(c not in '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ' for c in number):
        raise ValueError("Invalid input")

    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Base must be between 2 and 36")

    number = number.lower()
    if number[0] == '-':
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    decimal_value = 0
    for char in number:
        if '0' <= char <= '9':
            digit = ord(char) - ord('0')
        else:
            digit = ord(char) - ord('a') + 10

        if digit >= from_base:
            raise ValueError("Digit out of range for given base")

        decimal_value = decimal_value * from_base + digit

    if decimal_value == 0:
        return "0"

    result = ""
    while decimal_value > 0:
        remainder = decimal_value % to_base
        if remainder < 10:
            result += str(remainder)
        else:
            result += chr(remainder - 10 + ord('a'))
        decimal_value //= to_base

    if is_negative:
        result += '-'

    return result[::-1]
