def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    if not results:
        return []

    table = defaultdict(lambda: {'points': 0, 'goals_for': 0, 'goals_against': 0})

    for home, away, home_goals, away_goals in results:
        table[home]['goals_for'] += home_goals
        table[home]['goals_against'] += away_goals
        table[away]['goals_for'] += away_goals
        table[away]['goals_against'] += home_goals

        if home_goals > away_goals:
            table[home]['points'] += 3
        elif home_goals == away_goals:
            table[home]['points'] += 1
            table[away]['points'] += 1

    sorted_table = sorted(
        [(team, data['points'], data['goals_for'] - data['goals_against'], data['goals_for'])
         for team, data in table.items()],
        key=lambda x: (-x[1], -x[2], -x[3], x[0])
    )

    return sorted_table
