    if len(new_password) < 8:
        logging.warning(f"Email {email} rejected due to weak password")
        raise ValueError("Password must be at least 8 characters long")

    password_changed = set_password(email, new_password)

    if password_changed:
        logging.info(f"Email {email} updated")
    else:
        logging.info(f"Email {email} unknown")

    return password_changed
