            if char == '"':
                if in_quotes and field[-1] == '"':
                    field = field[:-1]
                    in_quotes = False
                elif not in_quotes:
                    in_quotes = True
            else:
                if in_quotes:
                    field += char
                else:
                    if char == ',':
                        fields.append(field)
                        field = ''
                    else:
                        field += char

        if field:
            fields.append(field)

        records.append(fields)

