from typing import List, Tuple

def schedule_jobs(jobs: List[Tuple[str, int, int]]) -> List[str]:
    # Sort jobs by profit in descending order, and by original index in case of tie
    jobs.sort(key=lambda x: (-x[2], -jobs.index(x)))

    # Initialize a list to keep track of scheduled jobs
    schedule = [None] * (max(job[1] for job in jobs))

    # Function to find the latest available slot before the deadline
    def find_latest_slot(deadline):
        for i in range(deadline - 1, -1, -1):
            if schedule[i] is None:
                return i
        return None

    # Schedule jobs
    for job_name, deadline, _ in jobs:
        slot = find_latest_slot(deadline)
        if slot is not None:
            schedule[slot] = job_name

    # Return the scheduled jobs in slot number order
    return [job for job in schedule if job is not None]

from typing import List, Tuple

def schedule_jobs(jobs: List[Tuple[str, int, int]]) -> List[str]:
    # Sort jobs by profit in descending order, and by original index for ties
    jobs.sort(key=lambda x: (-x[2], -jobs.index(x)))

    # Initialize a list to keep track of scheduled jobs
    schedule = [None] * (max(job[1] for job in jobs))

    # Function to find the latest available slot before the deadline
    def find_latest_slot(deadline):
        for i in range(deadline - 1, -1, -1):
            if schedule[i] is None:
                return i
        return None

    # Schedule each job
    for job_name, deadline, _ in jobs:
        slot = find_latest_slot(deadline)
        if slot is not None:
            schedule[slot] = job_name

    # Return the scheduled jobs in slot number order
    return [job for job in schedule if job is not None]

