import ast
import operator as op

ops = {
    ast.Add: op.add, ast.Sub: op.sub, ast.Mult: op.mul,
    ast.Div: op.truediv, ast.USub: op.neg, ast.Pow: op.pow, ast.BitXor: op.xor,
    ast.Lt: op.lt, ast.Lte: op.le, ast.Gt: op.gt, ast.Gte: op.ge, ast.Eq: op.eq, ast.NotEq: op.ne,
    ast.And: lambda x, y: all(x, y), ast.Or: lambda x, y: any(x, y), ast.Not: lambda x: not x
}

class FilterParser(ast.NodeVisitor):
    def visit_Name(self, node):
        try:
            return record[node.id]
        except KeyError:
            raise ValueError(f"Unknown variable: {node.id}")

    def visit_BinOp(self, node):
        left = self.visit(node.left)
        right = self.visit(node.right)
        return ops[type(node.op)](left, right)

    def visit_UnaryOp(self, node):
        operand = self.visit(node.operand)
        return ops[type(node.op)](operand)

    def visit_BoolOp(self, node):
        values = [self.visit(value) for value in node.values]
        return ops[type(node.op)](*values)

    def visit_Compare(self, node):
        left = self.visit(node.left)
        comparators = [self.visit(comparator) for comparator in node.comparators]
        ops_list = [ops[type(comp_op)] for comp_op in node.ops]
        return all(op(left, right) for op, right in zip(ops_list, comparators))

def matches_filter(expression: str, record: dict) -> bool:
    parsed_expression = ast.parse(expression, mode='eval').body
    return FilterParser().visit(parsed_expression)
