import heapq

def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    if start == goal:
        return 0, [start]

    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, w))
        graph[v].append((u, w))

    pq = [(0, start, [])]
    while pq:
        cost, node, path = heapq.heappop(pq)
        path = path + [node]
        if node == goal:
            return cost, path

        for neighbor, weight in graph[node]:
            if neighbor not in path:
                heapq.heappush(pq, (cost + weight, neighbor, path))

    return None
