def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [row[:] for row in matrix]

    def rotate_ring(ring):
        nonlocal k
        if k == 0:
            return ring
        elif k > 0:
            k %= len(ring)
        else:
            k = len(ring) + k % len(ring)

        return ring[-k:] + ring[:-k]

    top, bottom = 0, n - 1
    left, right = 0, n - 1

    while top < bottom and left < right:
        ring = []
        for i in range(left, right):
            ring.append(result[top][i])
