def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    num_cols = len(rows[0])
    col_widths = [max(len(cell) for cell in column) for column in zip(*rows)]

    formatted_rows = []
    for row, align in zip(rows, aligns):
        formatted_cells = []
        for cell, width, align_char in zip(row, col_widths, align):
            padding = " " * (width - len(cell))
            if align_char == 'l':
                formatted_cell = f"{cell}{padding}"
            elif align_char == 'r':
                formatted_cell = f"{padding}{cell}"
            else:  # center alignment
                half_padding = padding // 2
                if len(padding) % 2 != 0:
                    formatted_cell = f"{half_padding + 1}{cell}{half_padding}"
                else:
                    formatted_cell = f"{half_padding}{cell}{half_padding}"
            formatted_cells.append(formatted_cell)
        formatted_rows.append(" | ".join(formatted_cells))

    return "\n".join(formatted_rows)
