def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with http or https
    if not url.startswith(('http://', 'https://')):
        return False

    # Remove protocol part
    url = url[len('http://'):] if url.startswith('http://') else url[len('https://'):]

    # Check for invalid characters
    if any(c in url for c in r' \t\n\r\x00-\x1F\x7F'):
        return False

    # Split host and port
    parts = url.split('/')
    host_port = parts[0].split(':')
    host = host_port[0]

    # Check for localhost or .localhost
    if host == 'localhost' or host.endswith('.localhost'):
        return False

    # Validate DNS name
    labels = host.split('.')
    if len(labels[-1]) == 0 or not all(re.match(r'^[a-zA-Z0-9-]+$', label) for label in labels):
        return False

    # Check if last label is purely alphabetic
    if not re.match(r'^[a-zA-Z]+$', labels[-1]):
        return False

    # Check if port is present and valid
    if len(host_port) > 1:
        try:
            port = int(host_port[1])
            if port != 443:
                return False
        except ValueError:
            return False

    return True

