def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    max_instructions = 1000

    while ip < len(program):
        if ip > max_instructions:
            raise RuntimeError("Too many instructions")

        instruction = program[ip].split()
        op = instruction[0]

        if op == 'PUSH':
            n = int(instruction[1])
            stack.append(n)
        elif op == 'POP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif op == 'DUP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif op == 'SWAP':
            if len(stack) < 2:
                raise ValueError("Not enough elements for swap")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == 'ADD':
            if len(stack) < 2:
                raise ValueError("Not enough elements for addition")
            stack.append(stack.pop() + stack.pop())
        elif op == 'SUB':
            if len(stack) < 2:
                raise ValueError("Not enough elements for subtraction")
            a, b = stack.pop(), stack.pop()
            stack.append(b - a)
        elif op == 'MUL':
            if len(stack) < 2:
                raise ValueError("Not enough elements for multiplication")
            stack.append(stack.pop() * stack.pop())
        elif op == 'JMP':
            t = int(instruction[1])
            if t >= len(program):
                raise ValueError("Jump target out of bounds")
            ip = t - 1
        elif op == 'JZ':
            if len(stack) < 1:
                raise ValueError("Not enough elements for jump if zero")
            if stack[-1] == 0:
                t = int(instruction[1])
                if t >= len(program):
                    raise ValueError("Jump target out of bounds")
                ip = t - 1
            else:
                stack.pop()
        elif op == 'HALT':
            break
        else:
            raise ValueError(f"Unknown operation: {op}")

        ip += 1

    return stack
