from typing import List

def mean_and_median(numbers: List[float]) -> tuple[float, float]:
    if not numbers:
        raise ValueError("The list of numbers cannot be empty")

    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)
    mid = n // 2

    mean = round(sum(numbers) / n, 2)
    if n % 2 == 0:
        median = round((sorted_numbers[mid - 1] + sorted_numbers[mid]) / 2, 2)
    else:
        median = round(sorted_numbers[mid], 2)

    return (mean, median)
