def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0

    def popcount(x):
        return bin(x).count('1')

    # Using the inclusion-exclusion principle to count set bits in the range
    def bit_count(n):
        n += 1
        count = 0
        power_of_two = 1
        while power_of_two < n:
            count += (n // (power_of_two * 2)) * power_of_two
            remainder = n % (power_of_two * 2)
            if remainder >= power_of_two:
                count += remainder - power_of_two + 1
            power_of_two *= 2
        return count

    return bit_count(hi) - bit_count(lo - 1)
