from collections import deque

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    adj_list = [[] for _ in range(n)]
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    visited = [False] * n
    queue = deque([(source, 1)])
    visited[source] = True

    while queue:
        current, count = queue.popleft()
        if current == target:
            return count

        for neighbor in adj_list[current]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append((neighbor, count))

    return 0
