def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def within_bounds(r: int, c: int) -> bool:
        return 0 <= r < rows and 0 <= c < cols

    def toppling_occurred() -> bool:
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] >= 4:
                    return True
        return False

    def perform_topple(r: int, c: int) -> None:
        grid[r][c] -= 4
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if within_bounds(nr, nc):
                grid[nr][nc] += 1

    while toppling_occurred():
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] >= 4:
                    perform_topple(r, c)

    return [row[:] for row in grid]
