    teams = defaultdict(lambda: {'points': 0, 'goal_difference': 0, 'goals_scored': 0})

    for home, away, home_goals, away_goals in results:
        teams[home]['goals_scored'] += home_goals
        teams[away]['goals_scored'] += away_goals
        teams[home]['goal_difference'] += home_goals - away_goals
        teams[away]['goal_difference'] += away_goals - home_goals

