            teams[away]['points'] += 3
        else:
            teams[home]['points'] += 1
            teams[away]['points'] += 1

    return sorted(
        [(team, data['points'], data['goal_difference'], data['goals_scored']) for team, data in teams.items()],
        key=lambda x: (-x[1], -x[2], -x[3], x[0])
    )
