import ast

class FilterExpressionParser(ast.NodeTransformer):
    def __init__(self, record):
        self.record = record

    def visit_Name(self, node):
        if node.id in self.record:
            return ast.copy_location(
                ast.Num(self.record[node.id]), node)
        else:
            raise ValueError(f"Unknown variable: {node.id}")

    def visit_Compare(self, node):
        left = self.visit(node.left)
        comparators = [self.visit(comp) for comp in node.comparators]
        ops = [ast.Compare(left, op, right) for op, right in zip(node.ops, comparators)]
        return ast.BoolOp(ast.And(), ops)

    def visit_BinOp(self, node):
        left = self.visit(node.left)
        right = self.visit(node.right)
        return ast.BinOp(left, node.op, right)

    def visit_UnaryOp(self, node):
        operand = self.visit(node.operand)
        return ast.UnaryOp(node.op, operand)

def matches_filter(expression: str, record: dict) -> bool:
    try:
        parsed_expr = ast.parse(expression, mode='eval').body
        transformed_expr = FilterExpressionParser(record).visit(parsed_expr)
        return eval(compile(transformed_expr, filename="<ast>", mode="eval"))
    except (SyntaxError, NameError, TypeError) as e:
        raise ValueError("Invalid expression") from e
