                return False
        return True

    def backtrack(start, path):
        if start == len(guests):
            if is_valid(path):
                result.append(path[:])
            return
        for guest in guests:
            if guest not in path:
                path.append(guest)
                backtrack(start + 1, path)
                path.pop()

    result = []
    backtrack(0, [])
