from collections import deque

def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def slide(r, c, dr, dc):
        while 0 <= r + dr < rows and 0 <= c + dc < cols and grid[r + dr][c + dc] != '#':
            r += dr
            c += dc
        return r, c

    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1

    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        (r, c), steps = queue.popleft()
        if (r, c) == end:
            return steps

        for dr, dc in directions:
            nr, nc = slide(r, c, dr, dc)
            if (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append(((nr, nc), steps + 1))

    return -1
