def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix:
        return []

    n = len(matrix)
    result = [row[:] for row in matrix]

    def rotate_ring(ring):
        nonlocal k
        k %= len(ring)
        if k == 0:
            return
        ring[:k], ring[k:] = ring[-k:], ring[:-k]

    top, bottom = 0, n - 1
    left, right = 0, n - 1

    while top < bottom and left < right:
        ring = []
        for i in range(left, right + 1):
            ring.append(result[top][i])
        for i in range(top + 1, bottom + 1):
            ring.append(result[i][right])
        for i in range(right - 1, left - 1, -1):
            ring.append(result[bottom][i])
        for i in range(bottom - 1, top, -1):
            ring.append(result[i][left])

        rotate_ring(ring)

        for i in range(left, right + 1):
            result[top][i] = ring.pop(0)
        for i in range(top + 1, bottom + 1):
            result[i][right] = ring.pop(0)
        for i in range(right - 1, left - 1, -1):
            result[bottom][i] = ring.pop(0)
        for i in range(bottom - 1, top, -1):
            result[i][left] = ring.pop(0)

        top += 1
        bottom -= 1
        left += 1
        right -= 1

    return result
