from collections import OrderedDict

def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    if capacity == 0:
        return [], []

    cache = OrderedDict()
    results = []
    keys = []

    for op, key, *value in operations:
        if op == "put":
            if key in cache:
                del cache[key]
            if len(cache) >= capacity:
                cache.popitem(last=False)
            cache[key] = value[0]
        elif op == "get":
            if key in cache:
                value = cache[key]
                del cache[key]
                cache[key] = value
            else:
                value = None
            results.append(value)

    for _ in range(len(cache)):
        keys.append(next(iter(cache)))
        cache.move_to_end(keys[-1])

    return results, keys[::-1]
