                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == 'ADD':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() + stack.pop())
        elif op == 'SUB':
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif op == 'MUL':
            if len(stack) < 2:
