                target = int(instruction[1])
                if target >= 0:
                    ip = target
                    continue
            except ValueError:
                pass
        elif op == 'JZ':
            if not stack:
                return None
            if stack[-1] == 0:
                try:
                    target = int(instruction[1])
                    if target >= 0:
                        ip = target
                        continue
                except ValueError:
                    pass

        ip += 1
        max_executions -= 1

    return stack[::-1] if stack else None

